// Core tests: the 18 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC's tests section. Every expected value below was computed by hand
// from the SPEC's rules (integer cents and milli-percent, half-up once
// for tax and once for tip, remainder cents to the earliest payers).

import assert from "node:assert/strict";
import test from "node:test";
import { formatMoney, run } from "../public/js/core/bill-split.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

test("fixture count: 18 core and 3 controller cases are vendored", () => {
  assert.equal(coreCases.length, 18);
  assert.equal(fixtures.cases.filter((entry) => entry.kind === "controller").length, 3);
});

const base = {
  bill: "100.00",
  taxPercent: "10",
  tipPercent: "15",
  tipBase: "pre-tax",
  people: "3",
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("the legal maximums stay exact: bill 999999.99, both percents 100, 100 people", () => {
  const outcome = run({
    bill: "999999.99",
    taxPercent: "100",
    tipPercent: "100",
    tipBase: "post-tax",
    people: "100",
  });
  assert.equal(outcome.ok, true);
  const { sharesCents, ...scalars } = outcome.result;
  // tax = 99,999,999 (100% of the bill); base = 199,999,998; tip =
  // 199,999,998; total = 399,999,996 = 100 x 3,999,999 + 96, so the
  // first 96 people pay 4,000,000 and the last 4 pay 3,999,999.
  assert.deepEqual(scalars, {
    billCents: 99999999,
    taxCents: 99999999,
    tipBaseCents: 199999998,
    tipCents: 199999998,
    totalCents: 399999996,
  });
  assert.equal(sharesCents.length, 100);
  assert.equal(sharesCents[0], 4000000);
  assert.equal(sharesCents[95], 4000000);
  assert.equal(sharesCents[96], 3999999);
  assert.equal(sharesCents[99], 3999999);
  assert.equal(sharesCents.reduce((a, b) => a + b, 0), 399999996);
});

test("percent 100.000 is exactly at the limit and valid; 100.001 is RANGE", () => {
  const outcome = run({ ...base, taxPercent: "100.000", tipPercent: "0" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.taxCents, 10000);
  assert.deepEqual(errorOf({ ...base, taxPercent: "100.001" }), {
    code: "RANGE",
    field: "taxPercent",
    row: null,
  });
});

test("a bill of 1000000 passes grammar and capacity but is RANGE", () => {
  assert.deepEqual(errorOf({ ...base, bill: "1000000" }), {
    code: "RANGE",
    field: "bill",
    row: null,
  });
});

test("capacity is checked before grammar and range", () => {
  // 8 units > the percent limit of 7, even though the value is also bad.
  assert.deepEqual(errorOf({ ...base, taxPercent: "100.0000" }), {
    code: "INPUT_LIMIT",
    field: "taxPercent",
    row: null,
  });
  // 4 units > the people limit of 3.
  assert.deepEqual(errorOf({ ...base, people: "1000" }), {
    code: "INPUT_LIMIT",
    field: "people",
    row: null,
  });
  // 9 units > the tipBase limit of 8, even though it is not an enum value.
  assert.deepEqual(errorOf({ ...base, tipBase: "post-tax!" }), {
    code: "INPUT_LIMIT",
    field: "tipBase",
    row: null,
  });
});

test("bill grammar: leading zeros, bare dots, commas, spaces, full-width digits, three decimals", () => {
  for (const bill of ["01.00", ".5", "5.", "1,000", " 100", "１００", "0.005", "+100", "1e3"]) {
    assert.deepEqual(
      errorOf({ ...base, bill }),
      { code: "DECIMAL_FORMAT", field: "bill", row: null },
      `bill ${JSON.stringify(bill)}`,
    );
  }
});

test("people grammar: 007 and 3.0 are INTEGER_FORMAT; an empty people is EMPTY", () => {
  assert.deepEqual(errorOf({ ...base, people: "007" }), {
    code: "INTEGER_FORMAT",
    field: "people",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, people: "3.0" }), {
    code: "INTEGER_FORMAT",
    field: "people",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, people: "" }), {
    code: "EMPTY",
    field: "people",
    row: null,
  });
});

test("tipBase: case matters, empty is EMPTY, a near-miss is ENUM", () => {
  assert.deepEqual(errorOf({ ...base, tipBase: "PRE-TAX" }), {
    code: "ENUM",
    field: "tipBase",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, tipBase: "pre-taxx" }), {
    code: "ENUM",
    field: "tipBase",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, tipBase: "" }), {
    code: "EMPTY",
    field: "tipBase",
    row: null,
  });
});

test("a lone surrogate is UNICODE, after capacity and before grammar", () => {
  assert.deepEqual(errorOf({ ...base, bill: "12\uD800" }), {
    code: "UNICODE",
    field: "bill",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, people: "\uDC00" }), {
    code: "UNICODE",
    field: "people",
    row: null,
  });
});

test("the first field in the fixed order reports first", () => {
  assert.deepEqual(errorOf({ ...base, bill: "x", people: "0" }), {
    code: "DECIMAL_FORMAT",
    field: "bill",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, taxPercent: "x", tipPercent: "x" }), {
    code: "DECIMAL_FORMAT",
    field: "taxPercent",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, tipPercent: "101", tipBase: "gross", people: "0" }), {
    code: "RANGE",
    field: "tipPercent",
    row: null,
  });
  assert.deepEqual(errorOf({ ...base, tipBase: "gross", people: "0" }), {
    code: "ENUM",
    field: "tipBase",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, and accessor are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...base, extra: "1" }), schema);
  const missing = { ...base };
  delete missing.people;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...base, bill: 100 }), schema);
  assert.deepEqual(errorOf({ ...base, tipBase: null }), schema);
  assert.deepEqual(errorOf(["100.00"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("100.00"), schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "bill", {
    enumerable: true,
    get() {
      return "100.00";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
});

test("half-up: just below a half cent rounds down, an exact half rounds up", () => {
  // tax: 1004 x 10% = 100.4 -> 100.
  assert.deepEqual(run({ bill: "10.04", taxPercent: "10", tipPercent: "0", tipBase: "pre-tax", people: "1" }), {
    ok: true,
    result: { billCents: 1004, taxCents: 100, tipBaseCents: 1004, tipCents: 0, totalCents: 1104, sharesCents: [1104] },
  });
  // tip: 1005 x 10% = 100.5 -> 101 (the exact-half tie).
  assert.deepEqual(run({ bill: "10.05", taxPercent: "0", tipPercent: "10", tipBase: "pre-tax", people: "1" }), {
    ok: true,
    result: { billCents: 1005, taxCents: 0, tipBaseCents: 1005, tipCents: 101, totalCents: 1106, sharesCents: [1106] },
  });
});

test("switching only tipBase changes the tip and total, never the tax", () => {
  const pre = run(base);
  const post = run({ ...base, tipBase: "post-tax" });
  assert.equal(pre.ok, true);
  assert.equal(post.ok, true);
  assert.equal(pre.result.billCents, post.result.billCents);
  assert.equal(pre.result.taxCents, post.result.taxCents);
  assert.equal(pre.result.tipBaseCents, 10000);
  assert.equal(post.result.tipBaseCents, 11000);
  assert.notEqual(pre.result.tipCents, post.result.tipCents);
});

test("property over every successful fixture: shares sum to the total, differ by at most 1, non-increasing", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok) continue;
    const outcome = run(entry.input);
    assert.equal(outcome.ok, true, entry.id);
    const { sharesCents, totalCents } = outcome.result;
    assert.equal(sharesCents.length, Number.parseInt(entry.input.people, 10), entry.id);
    assert.equal(sharesCents.reduce((a, b) => a + b, 0), totalCents, entry.id);
    assert.ok(Math.max(...sharesCents) - Math.min(...sharesCents) <= 1, entry.id);
    for (let i = 1; i < sharesCents.length; i += 1) {
      assert.ok(sharesCents[i] <= sharesCents[i - 1], `${entry.id} share ${i}`);
    }
  }
});

test("display formatting: two decimals, no thousands separators, no currency symbol", () => {
  assert.equal(formatMoney(0), "0.00");
  assert.equal(formatMoney(5), "0.05");
  assert.equal(formatMoney(50), "0.50");
  assert.equal(formatMoney(4167), "41.67");
  assert.equal(formatMoney(99999999), "999999.99");
  assert.equal(formatMoney(123456789), "1234567.89");
  assert.equal(formatMoney(399999996), "3999999.96");
});
